import sys
from collections import defaultdict

def count_subsequences(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]

def find_subsequence_occuring_twice(s):
    n = len(s)
    if n < 2:
        return -1

    subsequences = defaultdict(int)

    for length in range(1, n + 1):
        for start in range(n - length + 1):
            subseq = s[start:start + length]
            count = count_subsequences(s, subseq)
            subsequences[subseq] = count

    for subseq, count in subsequences.items():
        if count == 2:
            return subseq

    return -1

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        S = input[index]
        index += 1
        result = find_subsequence_occuring_twice(S)
        results.append(result)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
